    ["05-d1"] = {name="领主大厅", entrance="铁炉堡 27.63, 47.83", pickup="走到丹莫罗与洛克莫丹时先接进本前的任务，进本前不必专程回头。天裔精灵不走 01-第9站：第一次到铁炉堡时往东到丹莫罗找大地先知法森，补做法森的守望、防患于未然和地下地图再回铁炉堡；不想绕路就略过旧铁炉堡入侵。", pickupS={{"走到丹莫罗与洛克莫丹时先接进本前的任务，进本前不必专程回头"}, {"天裔精灵不走 01-第9站：第一次到铁炉堡时往东到丹莫罗找大地先知法森，补做法森的守望、防患于未然和地下地图再回铁炉堡", {race={"天裔"}}}, {"不想绕路就略过旧铁炉堡入侵"}}, steps={[1]={npc="黑铁地图", npcObj=true, tag="副本前置链"}, [2]={npc="大地先知法森", tgt="大地先知法森", tag="副本前置链"}, [3]={npc="大地先知法森", tgt="大地先知法森"}, [4]={npc="阿法德拉·顿沃尔", tgt="阿法德拉·顿沃尔"}, [5]={npc="汤姆·费尔奇", tgt="汤姆·费尔奇"}, [6]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [7]={text="领主大厅 入口"}, [8]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [9]={hint="消灭15个被激怒的幽灵、10个被折磨的幽魂，让安威玛尔的灵魂得到安息。"}, [10]={hint="从领主大厅收集8件矮人传家宝。"}, [11]={hint="深入旧铁炉堡底层的领主大厅，拿回杜根·挽锤的徽记。"}, [12]={npc="Treaty of Understanding", npcObj=true, desc="右键背包里的谅解条约接任务。；尾王约 35% 血会恐惧，先清小怪，再把王拉回前一个房间打。；接任务处旁有拉杆，拉下开门就能直线跑出去。"}, [13]={npc="汤姆·费尔奇", tgt="汤姆·费尔奇"}, [14]={npc="阿法德拉·顿沃尔", tgt="阿法德拉·顿沃尔"}, [15]={npc="国王麦格尼·铜须", tgt="国王麦格尼·铜须"}, [16]={npc="国王麦格尼·铜须", tgt="国王麦格尼·铜须"}}},
    ["02-12"] = {steps={[1]={npc="格莱斯·瑟登", tgt="格莱斯·瑟登"}, [2]={node="铁炉堡"}, [4]={text="出铁炉堡沿大路往东，穿过东边山口的隧道进洛克莫丹，再沿路往东北到塞尔萨玛。", tag="还没开这个飞行点，第一次要用跑的"}, [5]={node="塞尔萨马尔"}, [6]={hint="南部警戒塔的巡山人格拉维戈要你杀掉10个碎石怪击颅者和10个碎石怪先知，然后回去向他汇报。"}, [7]={npc="巡山人格拉维戈", tgt="巡山人格拉维戈"}, [8]={npc="巡山人沃尔班", tgt="巡山人沃尔班"}, [9]={hint="使用生命符记复活丹莫罗的纳姆·法奥克。"}, [10]={npc="吉恩·角盔", tgt="吉恩·角盔"}, [11]={npc="布洛克·寻石者", tgt="布洛克·寻石者"}, [12]={npc="麦格玛尔·落斧", tgt="麦格玛尔·落斧"}, [13]={npc="麦格玛尔·落斧", tgt="麦格玛尔·落斧"}, [14]={npc="勘察员基恩萨·铁环", tgt="勘察员基恩萨·铁环"}, [15]={npc="年轻的达瑞尔", tgt="年轻的达瑞尔"}, [16]={hint="杀死6只山鹫，然后回到旅行者营地见年轻的达瑞尔，时限为15分钟。"}, [17]={npc="年轻的达瑞尔", tgt="年轻的达瑞尔"}, [18]={npc="年轻的达瑞尔", tgt="年轻的达瑞尔"}, [19]={hint="杀掉5只老山猪，然后回到旅行者营地去见年轻的达瑞尔，时限为12分钟。"}, [20]={npc="年轻的达瑞尔", tgt="年轻的达瑞尔"}, [21]={npc="马雷克·铁心", tgt="马雷克·铁心"}, [22]={npc="马雷克·铁心", tgt="马雷克·铁心"}, [23]={npc="宾格斯·雷管", tgt="宾格斯·雷管"}, [24]={npc="宾格斯·雷管", tgt="宾格斯·雷管"}, [25]={hint="找到并消灭那只名叫刀齿鳄的鳄鱼，把马雷克的刀给带回来。"}, [26]={hint="收集5块鳄鱼肉和6张鳄鱼皮，把它们交给旅行者营地里的马雷克·铁心。"}, [27]={hint="找回宾格斯的装备："}, [28]={hint="南部警戒塔的巡山人沃尔班要你杀掉10个碎石怪萨满祭司和10个碎石怪断骨者。"}, [29]={npc="主工程师辛德维尔七世", tgt="主工程师辛德维尔七世"}, [30]={npc="可疑的桶", npcObj=true}, [31]={npc="可疑的桶", npcObj=true}, [32]={npc="主工程师辛德维尔七世", tgt="主工程师辛德维尔七世"}, [33]={npc="宾格斯·雷管", tgt="宾格斯·雷管"}, [34]={npc="马雷克·铁心", tgt="马雷克·铁心"}, [35]={npc="马雷克·铁心", tgt="马雷克·铁心"}, [36]={hint="收集8个小石像，把它们交给麦格玛尔·落斧。"}, [37]={npc="麦格玛尔·落斧", tgt="麦格玛尔·落斧"}, [38]={npc="吉恩·角盔", tgt="吉恩·角盔"}, [39]={npc="吉恩·角盔", tgt="吉恩·角盔"}, [40]={npc="巡山人沃尔班", tgt="巡山人沃尔班"}, [42]={npc="阿古斯·夜语", tgt="阿古斯·夜语"}, [43]={npc="纳姆·法奥克", tgt="纳姆·法奥克"}, [44]={npc="纳姆·法奥克", tgt="纳姆·法奥克"}, [45]={hint="从盔枕湖附近的黑铁矮人那里取回一份黑铁手稿，把它交给铁炉堡的穆里顿·热炉。"}, [46]={npc="穆里顿·热炉", tgt="穆里顿·热炉"}, [47]={npc="穆里顿·热炉", tgt="穆里顿·热炉", desc="交任务学救赎。"}, [48]={npc="蒂萨·热炉", tgt="蒂萨·热炉", desc="交任务学救赎。"}, [49]={npc="艾兰娜瑞", tgt="艾兰娜瑞"}, [50]={npc="艾兰娜瑞", tgt="艾兰娜瑞"}, [51]={npc="玛希尔", tgt="玛希尔"}, [52]={npc="玛希尔", tgt="玛希尔", desc="奖励月神武器。"}, [53]={npc="玛希尔", tgt="玛希尔", desc="奖励月神武器。"}, [54]={npc="玛斯雷·驭熊者", tgt="玛斯雷·驭熊者", desc="在奥伯丁的月夜枭兽之石完成身心之力后，回达纳苏斯交，学熊形态。"}, [55]={npc="玛斯雷·驭熊者", tgt="玛斯雷·驭熊者"}, [56]={npc="德迪利特·星焰", tgt="德迪利特·星焰"}, [57]={npc="德迪利特·星焰", tgt="德迪利特·星焰"}, [58]={hint="使用空的峭壁之泉取样器在瀑布洞口获得水样。", desc="从永夜港搭德鲁伊专用的鸟到鲁瑟兰村，再飞奥伯丁。"}, [59]={npc="奥兰达利亚·夜歌", tgt="奥兰达利亚·夜歌"}, [60]={npc="奥兰达利亚·夜歌", tgt="奥兰达利亚·夜歌", desc="在黑海岸采地根草和月亮菇，回奥伯丁交。"}, [61]={hint="收集5个地根草和12个月亮菇，把它们交给奥伯丁的奥兰达利亚·夜歌，这样她就可以制作解药了。", desc="在黑海岸采地根草和月亮菇，回奥伯丁交。"}, [62]={npc="奥兰达利亚·夜歌", tgt="奥兰达利亚·夜歌", desc="在黑海岸采地根草和月亮菇，回奥伯丁交。"}, [63]={npc="奥兰达利亚·夜歌", tgt="奥兰达利亚·夜歌", desc="用解药治疗黑海岸生病的鹿。"}, [64]={hint="对黑海岸的10头生病的鹿使用动物医疗药膏，以此来治疗它们。从壁泉河到奥伯丁，直到最南端靠近灰谷的地区都有生病的鹿出没。", desc="用解药治疗黑海岸生病的鹿。"}, [65]={npc="德迪利特·星焰", tgt="德迪利特·星焰", desc="治好 10 头鹿后用传送：月光林地回去交。"}, [66]={npc="德迪利特·星焰", tgt="德迪利特·星焰", desc="交任务学解毒术。"}, [67]={npc="玛斯雷·驭熊者", tgt="玛斯雷·驭熊者", desc="交任务学解毒术。从永夜港搭德鲁伊专用的鸟到鲁瑟兰村，走村内传送门进达纳苏斯。"}, [68]={npc="玛斯雷·驭熊者", tgt="玛斯雷·驭熊者"}, [69]={npc="德迪利特·星焰", tgt="德迪利特·星焰"}, [70]={npc="德迪利特·星焰", tgt="德迪利特·星焰", desc="在月神湖底找到神殿灵珠。"}, [71]={hint="在月神湖寻找神殿灵珠，把它带到月光林地西北部的雷姆洛斯神殿去。在神殿中使用神殿灵珠，然后与神殿中的塔加里谈话来完成试炼。", desc="在月神湖底找到神殿灵珠。"}, [72]={npc="塔加里", tgt="塔加里", desc="在月神湖底找到神殿灵珠。"}, [73]={npc="塔加里", tgt="塔加里", desc="两个奇怪的带锁箱各装半块坠饰，一个在黑海岸奥伯丁北方的海底，一个在西部荒野西北海岸外的海底。"}, [74]={hint="寻找水兽耐力坠饰和水兽敏捷坠饰。与月光林地的居民谈一谈，找出这些东西可能被放在哪里。", desc="从永夜港搭德鲁伊专用的鸟到鲁瑟兰村，飞奥伯丁，往北游到海底的带锁箱；再从奥伯丁搭船到暴风城，飞哨兵岭，往西北到海岸外游下去开另一个带锁箱。"}, [75]={text="集齐两半后用传送：月光林地回去，在雷姆洛斯神殿附近把坠饰合成一个。"}, [76]={npc="德迪利特·星焰", tgt="德迪利特·星焰"}, [77]={npc="德迪利特·星焰", tgt="德迪利特·星焰", desc="交任务学水栖形态。"}, [78]={npc="玛斯雷·驭熊者", tgt="玛斯雷·驭熊者", desc="交任务学水栖形态。从永夜港搭德鲁伊专用的鸟到鲁瑟兰村，走村内传送门进达纳苏斯。"}}},
    ["02-13"] = {steps={[1]={npc="古博·布拉普", tgt="古博·布拉普"}, [2]={npc="通缉：莫克迪普！", npcObj=true}, [3]={npc="考古学家霍莉", tgt="考古学家霍莉"}, [4]={npc="考古学家霍莉", tgt="考古学家霍莉"}, [5]={npc="桑迪斯·织风", tgt="桑迪斯·织风"}, [6]={npc="高尔博德·钢手", tgt="高尔博德·钢手"}, [7]={npc="高尔博德·钢手", tgt="高尔博德·钢手"}, [8]={npc="戈沙拉·夜语", tgt="戈沙拉·夜语"}, [9]={npc="特伦希斯", tgt="特伦希斯"}, [10]={npc="特伦希斯", tgt="特伦希斯"}, [11]={npc="神秘的红色水晶", npcObj=true}, [12]={npc="神秘的红色水晶", npcObj=true}, [13]={npc="阿斯特利安", tgt="阿斯特利安"}, [14]={npc="搁浅的海洋生物", npcObj=true}, [15]={hint="为奥伯丁的高尔博德·钢手找回银色清晨号和迷雾之纱号的保险箱。两只箱子都在村庄北面的沉船残骸中。"}, [16]={npc="传声盒411号", npcObj=true}, [17]={npc="传声盒411号", npcObj=true}, [18]={npc="搁浅的海龟", npcObj=true}, [19]={text="沿路跑到这个点。", desc="接下来沿路见到月夜猛虎幼崽和狂暴蓟熊就打。"}, [20]={text="沿路跑到这个点。"}, [21]={hint="到奥伯丁的北面去，沿着壁泉河到达第一个瀑布处，从瀑布下的水潭中取出一份水样。"}, [22]={hint="收集6块优质蟹肉，把它们交给奥伯丁的古博·布拉普。"}, [23]={npc="搁浅的海龟", npcObj=true}, [24]={npc="巴苏尔·影击", tgt="巴苏尔·影击"}, [25]={npc="巴苏尔·影击", tgt="巴苏尔·影击"}, [26]={hint="在奥萨拉克斯之塔附近帮巴苏尔·影击收集4块破旧的羊皮纸。"}, [27]={npc="巴苏尔·影击", tgt="巴苏尔·影击"}, [28]={npc="巴苏尔·影击", tgt="巴苏尔·影击"}, [29]={hint="到森林里去杀掉20头狂暴蓟熊。"}, [30]={hint="收集6颗月夜猛虎的牙齿，把它们放进传声盒323号。"}, [31]={hint="收集5个粗柄蘑菇和1个毒帽蘑菇，把它们交给奥伯丁的巴瑞萨斯·月影。"}, [32]={npc="传声盒323号", npcObj=true}, [33]={npc="传声盒323号", npcObj=true}, [34]={npc="萨纳瑞恩·绿树", tgt="萨纳瑞恩·绿树"}, [35]={npc="萨纳瑞恩·绿树", tgt="萨纳瑞恩·绿树"}, [36]={npc="高尔博德·钢手", tgt="高尔博德·钢手"}, [37]={npc="桑迪斯·织风", tgt="桑迪斯·织风"}, [38]={npc="桑迪斯·织风", tgt="桑迪斯·织风"}, [39]={npc="哨兵戈琳达·纳希恩", tgt="哨兵戈琳达·纳希恩"}, [40]={npc="巴瑞萨斯·月影", tgt="巴瑞萨斯·月影", desc="到月井把空的净化碗装满。"}, [41]={npc="巴瑞萨斯·月影", tgt="巴瑞萨斯·月影"}, [42]={npc="温尼斯·布莱葛", tgt="温尼斯·布莱葛"}, [43]={npc="温尼斯·布莱葛", tgt="温尼斯·布莱葛"}, [44]={npc="温尼斯·布莱葛", tgt="温尼斯·布莱葛"}, [45]={npc="古博·布拉普", tgt="古博·布拉普"}, [46]={npc="搁浅的海洋生物", npcObj=true}, [47]={npc="搁浅的海洋生物", npcObj=true, desc="靠近营火才会触发事件，现在打或晚点路线再经过时打都行。"}, [48]={npc="搁浅的海龟", npcObj=true}, [49]={npc="搁浅的海龟", npcObj=true}, [50]={npc="搁浅的海洋生物", npcObj=true}, [51]={text="沿路跑到这个点。"}, [52]={npc="哨兵阿娜莎", tgt="哨兵阿娜莎", desc="往下一个任务途中，看到月夜雄虎就打（幼崽和