    ["03-28"] = {steps={[2]={npc="哨兵梅丽瑞亚·霜影", tgt="哨兵梅丽瑞亚·霜影"}, [3]={npc="伊莉亚娜", tgt="伊莉亚娜"}, [4]={npc="皮尔图拉斯·怀特姆恩", tgt="皮尔图拉斯·怀特姆恩"}, [5]={text="沿路跑到这个点。"}, [6]={text="沿路跑到这个点。"}, [7]={hint="到狼嚎谷去，研究一下麦尔莎迪丝之书，然后向艾森娜神殿的哨兵梅丽瑞亚·霜影复命。", desc="从山洞进去拿书，容易多拉怪，稀有怪在时更难。"}, [8]={text="沿路跑到这个点。"}, [9]={hint="从沼泽兽智者那里取回一枚陨落的月亮石，并把它带给阿斯特兰纳的皮尔图拉斯·怀特姆恩。"}, [10]={text="沿路跑到这个点。"}, [11]={hint="在夜道谷和萨提纳尔找到被禁锢的上层精灵的灵魂，释放它们，然后回到迈斯特拉岗哨的净化者德尔格伦那里。"}, [12]={npc="安妮莉亚", tgt="安妮莉亚"}, [13]={npc="安妮莉亚", tgt="安妮莉亚"}, [14]={hint="杀掉加萨里斯，把塞纳留斯的树枝交给艾森娜神殿的伊莉亚娜。"}, [15]={npc="凯尼斯·静风", tgt="凯尼斯·静风"}, [16]={npc="马塞拉·秋月", tgt="马塞拉·秋月"}, [17]={hint="马塞拉·秋月要你前往林歌神殿以西、萨提纳尔恶魔盘踞的区域搜寻。回来后向她报告丈夫库罗塞尔的任何线索。"}, [18]={npc="马塞拉·秋月", tgt="马塞拉·秋月"}, [19]={node="塔伦迪斯营地"}, [21]={npc="皮尔图拉斯·怀特姆恩", tgt="皮尔图拉斯·怀特姆恩"}, [22]={npc="哨兵梅丽瑞亚·霜影", tgt="哨兵梅丽瑞亚·霜影"}, [23]={npc="哨兵梅丽瑞亚·霜影", tgt="哨兵梅丽瑞亚·霜影", tag="可选"}, [24]={npc="伊莉亚娜", tgt="伊莉亚娜"}, [25]={npc="净化者德尔格伦", tgt="净化者德尔格伦"}}},
    ["03-29"] = {steps={[1]={tag="可选", desc="达纳苏斯这段经验少，赶路可跳过。"}, [2]={text="走进鲁瑟兰村的传送门到达纳苏斯。", tag="可选"}, [3]={npc="塞恩提尔·刃纹", tgt="塞恩提尔·刃纹", tag="可选"}, [4]={npc="塞恩提尔·刃纹", tgt="塞恩提尔·刃纹", tag="可选"}, [5]={hint="在维琳德的箱子里搜寻她的日记，把日记连同钥匙一起交给达纳苏斯的塞恩提尔·刃纹。", tag="可选"}, [6]={npc="塞恩提尔·刃纹", tgt="塞恩提尔·刃纹", tag="可选"}, [7]={npc="塞恩提尔·刃纹", tgt="塞恩提尔·刃纹", tag="可选"}, [8]={text="走进达纳苏斯的传送门回鲁瑟兰村。", tag="可选"}, [9]={text="做了达纳苏斯选做的从鲁瑟兰村飞棘齿城（经奥伯丁、塔伦迪斯营地），跳过的从阿斯特兰纳飞（经塔伦迪斯营地）；沿主路往南，绕开陶拉祖营地，搭大升降梯下千针石林。两点没开才走莫尔杉壁垒。"}, [10]={text="沿路跑到这个点。"}, [11]={node="萨兰纳尔"}, [12]={npc="维兹尔·铜栓", tgt="维兹尔·铜栓"}, [13]={npc="维兹尔·铜栓", tgt="维兹尔·铜栓"}, [14]={npc="菲兹尔·铜栓", tgt="菲兹尔·铜栓"}, [15]={npc="克拉维尔·浓须", tgt="克拉维尔·浓须"}, [16]={npc="克拉维尔·浓须", tgt="克拉维尔·浓须"}, [17]={npc="克拉维尔·浓须", tgt="克拉维尔·浓须"}, [18]={npc="普兹克", tgt="普兹克"}, [19]={npc="赛道管理员泽尔林", tgt="赛道管理员泽尔林"}, [20]={hint="给闪光平原的普兹克找10根空心秃鹫骨。"}, [21]={hint="为闪光平原的赛道管理员泽尔林杀死10条盐石蜥蜴、10条盐石水晶蜥蜴和6条盐石凝视者。"}, [22]={hint="收集9块硬化龟壳，把它们交给闪光平原的维兹尔·铜栓。"}, [23]={hint="收集30个火箭车零件，把它们交给闪光平原的克拉维尔·浓须。"}, [24]={hint="为闪光平原的菲兹尔·铜栓带去6份含盐的蝎毒。"}, [25]={npc="普兹克", tgt="普兹克"}, [26]={npc="赛道管理员泽尔林", tgt="赛道管理员泽尔林"}, [27]={npc="维兹尔·铜栓", tgt="维兹尔·铜栓"}, [28]={npc="菲兹尔·铜栓", tgt="菲兹尔·铜栓"}, [29]={npc="克拉维尔·浓须", tgt="克拉维尔·浓须"}, [30]={text="从闪光平原沿大路往南进塔纳利斯，到加基森开飞行点再炉石。", tag="还没开这个飞行点，第一次要用跑的"}, [31]={node="加基森"}}},
