    ["03-38"] = {steps={[1]={desc="已开尼耶尔前哨站就直接飞过去（经塞拉摩），跳过下一步。石爪峰没开就飞阿斯特兰纳，从灰谷南边的山洞进石爪山脉。"}, [2]={text="从石爪峰沿大路往南下山，经过烈日石居时绕开部落营地，从石爪山脉西南边进凄凉之地，尼耶尔前哨站在凄凉之地北边。", tag="还没开这个飞行点，第一次要用跑的"}, [3]={node="尼耶尔前哨站"}, [4]={npc="安东修士", tgt="安东修士"}, [5]={npc="霍恩尼兹", tgt="霍恩尼兹"}, [6]={npc="智者乌泰克", tgt="智者乌泰克"}, [7]={npc="智者乌泰克", tgt="智者乌泰克"}, [8]={hint="杀掉30个亡灵劫掠者，然后向尼耶尔前哨站的安东修士复命。"}, [9]={hint="把幽灵磁铁箱和8份幽灵电浆交给凄凉之地的霍恩尼兹。"}, [11]={hint="把杰恩可汗的头颅交给凄凉之地吉尔吉斯村的智者乌泰克。"}, [12]={npc="智者乌泰克", tgt="智者乌泰克"}, [13]={npc="智者乌泰克", tgt="智者乌泰克", tag="可选"}, [14]={hint="继续和吉尔吉斯部族保持良好的关系，把玛洛迪钥匙碎片交给吉尔吉斯村的智者乌泰克。", tag="可选", desc="专程绕路，附近没有其他目标；赶路可跳过。"}, [15]={npc="智者乌泰克", tgt="智者乌泰克", tag="可选"}, [16]={npc="霍恩尼兹", tgt="霍恩尼兹"}, [17]={npc="安东修士", tgt="安东修士"}}},
