    ["04-44"] = {steps={[1]={desc="南海镇没开就飞米奈希尔港，搭北边码头往奥伯丁的船，在南海镇下船。"}, [2]={text="沿路跑到这个点。"}, [3]={npc="弗斯塔德·蛮锤", tgt="弗斯塔德·蛮锤"}, [4]={node="鹰巢山"}, [5]={npc="弗斯塔德·蛮锤", tgt="弗斯塔德·蛮锤"}, [6]={npc="狮鹫管理员沙拉克·鹰斧", tgt="狮鹫管理员沙拉克·鹰斧"}, [7]={npc="狮鹫管理员沙拉克·鹰斧", tgt="狮鹫管理员沙拉克·鹰斧"}, [8]={npc="弗拉加尔", tgt="弗拉加尔"}, [9]={npc="弗拉加尔", tgt="弗拉加尔"}, [10]={text="在鹰巢山旅店绑炉石（13.80, 41.60）。"}, [11]={hint="为鲁瑟兰村的艾瑞拉斯·琥珀收集15支枭兽羽毛。"}, [12]={hint="检查两个枯木巨魔村落里的笼子，然后向狮鹫管理员沙拉克·鹰斧回复。"}, [14]={hint="给鹰巢山的弗拉加尔带去5条巨魔部族项链。"}, [15]={hint="加基森的斯普琳科要你去给她找到一颗紫色水生菇。"}, [16]={hint="杀掉10个绿色淤泥怪和10个玉石软泥怪，然后回到鹰巢山向弗拉加尔报告。"}, [17]={npc="弗拉加尔", tgt="弗拉加尔"}, [18]={npc="弗拉加尔", tgt="弗拉加尔"}, [19]={npc="狮鹫管理员沙拉克·鹰斧", tgt="狮鹫管理员沙拉克·鹰斧"}, [20]={npc="狮鹫管理员沙拉克·鹰斧", tgt="狮鹫管理员沙拉克·鹰斧"}, [21]={hint="检查祖尔祭坛的顶部，然后向狮鹫管理员沙拉克·鹰斧报告。"}, [22]={npc="OOX-09/HL定位器", npcObj=true, desc="右键背包里的OOX-09/HL定位器接任务。"}, [23]={npc="自动导航机器人OOX-09/HL", tgt="自动导航机器人OOX-09/HL"}, [24]={npc="自动导航机器人OOX-09/HL", tgt="自动导航机器人OOX-09/HL"}, [25]={hint="将OOX-09/HL护送到被遗忘的海岸上的码头，然后向藏宝海湾的奥格索普·奥布诺提斯报告。"}, [26]={hint="用超级摄影器FX给加莫里塔拍张照片，然后把它交给鲁瑟兰村的达蕾恩·轻风。"}, [27]={hint="藏宝海湾的威士忌斯利姆想要你帮他找回弄丢的紫葡萄酒。"}, [29]={npc="狮鹫管理员沙拉克·鹰斧", tgt="狮鹫管理员沙拉克·鹰斧"}, [30]={npc="狮鹫管理员沙拉克·鹰斧", tgt="狮鹫管理员沙拉克·鹰斧"}, [32]={text="在塞尔萨马尔旅店绑炉石（35.40, 48.40）。"}, [33]={text="沿路跑到这个点。"}, [34]={npc="维里克·雷锤", tgt="维里克·雷锤"}, [35]={hint="使用扭曲的图腾，终结野猪人的仪式。", desc="避难谷地飞米奈希尔港，南码头搭船到塞拉摩，飞萨兰纳尔，往东走进千针石林。"}, [36]={npc="维里克·雷锤", tgt="维里克·雷锤", desc="萨兰纳尔飞塞拉摩，搭船到米奈希尔港，飞避难谷地。"}, [37]={npc="维里克·雷锤", tgt="维里克·雷锤"}, [38]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉"}, [39]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉"}, [40]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", desc="击败塞克隆尼亚取得精华。"}, [41]={hint="把巴斯拉的羊皮纸上列出的东西交给奥特兰克的捕风者巴斯拉。", desc="击败塞克隆尼亚取得精华。"}, [42]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", desc="击败塞克隆尼亚取得精华。"}, [43]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉"}, [44]={hint="将旋风之心带给捕风者巴斯拉。"}, [45]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉"}, [46]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", desc="奖励旋风武器。"}, [47]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", desc="奖励旋风武器。"}}},
    ["04-45"] = {steps={[1]={npc="西格鲁·铁斧", tgt="西格鲁·铁斧", tag="可选"}, [2]={npc="加瑞克", tgt="加瑞克", tag="可选"}, [3]={hint="用大地印章激活钻石之柱、欧泊之柱和紫水晶之柱并拿到三颗符石。", tag="之后顺路", desc="沿途通常会掉炽热魔符；没掉就放弃。"}, [4]={npc="大地封印", npcObj=true, tag="可选"}, [5]={npc="加瑞克", tgt="加瑞克", tag="可选"}, [6]={npc="西格鲁·铁斧", tgt="西格鲁·铁斧", tag="可选"}, [7]={hint="杀死苦痛堡垒中的因弗努斯大使，把证明他已死亡的信物交给铁炉堡的顾问贝尔格拉姆。"}, [8]={text="从荒芜之地往西走，经部落营地卡加斯旁的山路进灼热峡谷，卡加斯要绕开。", tag="还没开这个飞行点，第一次要用跑的"}, [9]={npc="木制厕所", npcObj=true}, [10]={hint="杀掉8个黑铁地质学家，并将15块丝绸交给灼热峡谷里那个被锁在厕所中的矮人。"}, [11]={text="击杀狂暴的玛尔戈，经验很多。", tag="可选", desc="玛尔戈的角开灼热峡谷钥匙任务线；不打就跳过第 12、31-32、34、36、39-41 步，第 42 步从铁炉堡飞回瑟银哨塔。"}, [12]={npc="玛尔戈的角", npcObj=true, tag="可选", desc="右键背包里的玛尔戈的角接任务。"}, [13]={npc="木制厕所", npcObj=true}, [14]={npc="木制厕所", npcObj=true}, [15]={hint="把古德斯迪尔的账本和上面所列的物品交给塔纳利斯的克林科·古德斯迪尔。"}, [16]={npc="杜里奥斯·裂石", tgt="杜里奥斯·裂石"}, [17]={npc="烧焦的信件", npcObj=true}, [18]={npc="烧焦的信件", npcObj=true}, [19]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [20]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [21]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [22]={nodeA="{a:1446}"}, [23]={npc="通缉/寻物/招领", npcObj=true, tag="可选"}, [24]={npc="通缉/寻物/招领", npcObj=true}, [25]={npc="通缉/寻物/招领", npcObj=true}, [26]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳"}, [27]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳", tag="可选"}, [28]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳"}, [29]={npc="大铁匠博恩奈特", tgt="大铁匠博恩奈特"}, [31]={npc="巡山人贝波蒂", tgt="巡山人贝波蒂", tag="可选"}, [32]={npc="巡山人贝波蒂", tgt="巡山人贝波蒂", tag="可选"}, [34]={npc="索里奥斯馆长", tgt="索里奥斯馆长", tag="可选"}, [35]={npc="索里奥斯馆长", tgt="索里奥斯馆长"}, [36]={npc="索里奥斯馆长", tgt="索里奥斯馆长", tag="可选"}, [37]={npc="索里奥斯馆长", tgt="索里奥斯馆长"}, [38]={npc="顾问贝尔格拉姆", tgt="顾问贝尔格拉姆"}, [39]={tag="可选", desc="有馆长的证明（馆长的证明！）才回贝波蒂拿钥匙；没有就跳到第 42 步。"}, [40]={npc="巡山人贝波蒂", tgt="巡山人贝波蒂", tag="可选"}, [41]={text="用刚拿到的灼热峡谷钥匙打开巡山人贝波蒂旁的大门，穿过隧道进灼热峡谷。", tag="可选"}, [42]={tag="可选", desc="没有灼热峡谷钥匙的人从铁炉堡直飞回灼热峡谷；已经穿隧道进来的跳过。"}, [43]={hint="收集4份烈焰之心和4份傀儡之油，然后把这些东西交给威拉罗克·温布雷。"}, [44]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [45]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [46]={hint="找到冶炼鼓风机和侦查员的望远镜，把它们还给灼热峡谷的监