    ["05-d11"] = {name="黑石深渊", entrance="灼热峡谷 34.80, 85.30", steps={[1]={npc="弗兰克罗恩·铸铁", tgt="弗兰克罗恩·铸铁"}, [2]={npc="弗兰克罗恩·铸铁", tgt="弗兰克罗恩·铸铁"}, [3]={npc="弗兰克罗恩·铸铁", tgt="弗兰克罗恩·铸铁"}, [4]={text="黑石深渊 入口"}, [5]={hint="杀掉弗诺斯·达克维尔并拿回战锤铁胆。把铁胆之锤拿到索瑞森神殿去，将其放在弗兰克罗恩·铸铁的雕像上。"}, [6]={npc="弗兰克罗恩·铸铁的雕像", npcObj=true}}},
