    ["04-48"] = {steps={[1]={text="从塔纳利斯西边的山路走坡道下安戈洛环形山，托尔瓦·寻路者就在坡道底的入口旁。", tag="还没开这个飞行点，第一次要用跑的"}, [2]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [3]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [4]={npc="破碎的木筏", npcObj=true, desc="收集红、蓝、绿、黄水晶各 7 个，并从迅猛龙身上拿被撕破的日记。"}, [5]={npc="小背包", npcObj=true}, [6]={npc="小背包", npcObj=true}, [7]={hint="找到拉克维刚刚猎杀的动物的尸体，从尸体上偷取一块蛇颈龙肉块，然后回到安戈洛环形山的托尔瓦·寻路者那里。"}, [8]={desc="在 67.7, 30.7 一带打植物，练到 49 级一半。"}, [9]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [10]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [11]={hint="将2份暴掠龙信息素交给安戈洛尔环形山入口附近的托尔瓦·寻路者。"}, [12]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [13]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [14]={hint="使用托尔瓦的麻袋中的东西召唤拉克维并打败它。将拉克维的头颅交给安戈洛环形山入口处的托尔瓦·寻路者。", tag="可选", desc="这件较难，可留到回安戈洛时再做。"}, [15]={npc="卡尔纳·雷塔维", tgt="卡尔纳·雷塔维"}, [16]={npc="林克", tgt="林克"}, [17]={npc="林克", tgt="林克"}, [18]={nodeA="{a:541}"}, [19]={npc="威利德·马绍尔", tgt="威利德·马绍尔"}, [20]={npc="霍莱伊·马绍尔", tgt="霍莱伊·马绍尔"}, [21]={npc="斯巴克·尼米尔", tgt="斯巴克·尼米尔"}, [22]={npc="科琳", tgt="科琳"}, [23]={npc="科琳", tgt="科琳"}, [24]={npc="科琳", tgt="科琳"}, [25]={npc="科琳", tgt="科琳"}, [26]={npc="科琳", tgt="科琳"}, [27]={npc="当心翼手龙", npcObj=true}, [28]={npc="穆尔金", tgt="穆尔金"}, [29]={npc="希兹尔", tgt="希兹尔"}, [30]={hint="在安戈洛尔环形山找到北部水晶塔。"}, [31]={hint="将2块安戈洛猩猩的皮、2块安戈洛大猩猩的皮和2块安戈洛巨猩猩的皮交给安戈洛环形山入口处的托尔瓦·寻路者。"}, [33]={hint="将食物箱和研究设备交给安戈洛环形山的威利德·马绍尔。"}, [34]={hint="在安戈洛尔环形山找到东部水晶塔。"}, [35]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [36]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [37]={text="沿路跑到这个点。"}, [38]={text="沿路跑到这个点。"}, [39]={hint="使用采集瓶从安戈洛环形山的某个格里什虫巢的孵化室中收集一份巢穴侧壁的样本，在有悬挂着的虫卵的房间里收集样本。"}, [40]={hint="在安戈洛尔环形山找到西部水晶塔。"}, [41]={text="把手上的击杀、收集任务做完。"}, [42]={hint="为马绍尔营地的希兹尔收集8块精细的双帆龙鳞片和8块精细的翼手龙鳞片。"}, [43]={hint="从安戈洛尔环形山的血瓣花猛击者和血瓣花掠夺者身上收集15个血瓣花，然后向穆尔金回复。"}, [44]={hint="杀掉10只翼手龙和15只狂怒的翼手龙，然后向马绍尔营地的斯普拉格·弗劳克报告。"}, [45]={npc="希兹尔", tgt="希兹尔"}, [46]={npc="穆尔金", tgt="穆尔金"}, [47]={npc="穆尔金", tgt="穆尔金"}, [48]={npc="斯普拉格·弗劳克", tgt="斯普拉格·弗劳克"}, [49]={npc="斯巴克·尼米尔", tgt="斯巴克·尼米尔"}, [50]={npc="霍莱伊·马绍尔", tgt="霍莱伊·马绍尔"}, [51]={npc="威利德·马绍尔", tgt="威利德·马绍尔"}, [52]={npc=