gt="奥汀克"}, [99]={npc="奥汀克", tgt="奥汀克"}, [100]={hint="将6块碎浪多头怪的鳞片交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶部。"}, [101]={npc="奥汀克", tgt="奥汀克"}, [102]={npc="奥汀克", tgt="奥汀克", desc="绿龙在阿塔哈卡神庙。"}, [103]={hint="将摩弗拉斯的牙齿交给艾萨拉的奥汀克。他住在埃达拉斯废墟东北部悬崖的顶端。", desc="绿龙在阿塔哈卡神庙。"}, [104]={npc="奥汀克", tgt="奥汀克", desc="绿龙在阿塔哈卡神庙。"}, [105]={text="走进达纳苏斯的传送门回鲁瑟兰村。"}, [107]={text="在阿斯特兰纳旅店绑炉石（37.00, 49.20）。"}}},
    ["04-49"] = {steps={[1]={text="从阿斯特兰纳沿大路往北进费伍德森林。", tag="还没开这个飞行点，第一次要用跑的"}, [2]={npc="阿拉珊蒂丝·银空", tgt="阿拉珊蒂丝·银空"}, [3]={npc="格拉兹", tgt="格拉兹"}, [4]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [5]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [6]={npc="塔诺恩·红羽", tgt="塔诺恩·红羽", tag="可选"}, [7]={hint="格拉兹要你去杀死6个死木战士、6个死木探路者以及6个死木园丁。"}, [8]={npc="格拉兹", tgt="格拉兹"}, [9]={npc="格拉兹", tgt="格拉兹"}, [10]={hint="杀掉11个碧火魔仆、9个碧火巡影者、9个碧火潜行者和萨瓦瑟拉斯。任务完成之后回到费伍德森林的艾瑞丹·蓝风处复命。"}, [11]={hint="到加德纳尔去杀掉4个加德纳尔恶犬、4个加德纳尔守护者、6个加德纳尔精兵和6个加德纳尔祭司，然后向费伍德森林的格雷塔·苔蹄复命。"}, [12]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [13]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [14]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [15]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [16]={hint="把空壶拿到加德纳尔中心的月亮井去，装满井水之后再回到费伍德森林的格雷塔·苔蹄那里。"}, [17]={desc="在加德纳尔 35, 59 一带打怪。"}, [18]={hint="杀掉2个热能野兽和2个热能恐兽，并探索碎痕谷。然后查看凹坑中是否仍然充满了堕落的恶臭之水，完成这些任务之后，向费伍德森林中的塔诺恩·红羽复命。", tag="可选", desc="专程绕路，附近没有其他目标；赶路可跳过。"}, [19]={hint="费伍德森林的艾瑞丹·蓝风要你去杀掉8个碧火唤魔者、8个碧火背叛者、8个碧火欺诈者和萨瓦里克。任务完成之后回到艾瑞丹那里复命。"}, [20]={npc="萨瓦里克长笛", npcObj=true, desc="右键背包里的萨瓦里克长笛接任务。"}, [21]={hint="将萨瓦里克长笛和5个碧火魔符交给费伍德森林南部的艾瑞丹·蓝风。"}, [22]={hint="收集15颗血琥珀，把它们交给费伍德森林的阿拉珊蒂丝·银空。"}, [23]={node="刺枝林地"}, [24]={npc="纳菲恩", tgt="纳菲恩"}, [25]={npc="纳菲恩", tgt="纳菲恩", tag="需游戏内实测"}, [26]={hint="格拉兹要你去杀死6个死木守卫、6个死木复仇者和6个死木萨满祭司。", tag="需游戏内实测"}, [27]={npc="纳菲恩", tgt="纳菲恩", tag="需游戏内实测"}, [28]={text="沿路跑到这个点。", desc="从这里进木喉要塞的山洞，穿过去就是冬泉谷。"}, [29]={npc="萨尔法", tgt="萨尔法", tag="需游戏内实测"}, [30]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [31]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [32]={npc="麦吉·贝比罗克", tgt="麦吉·贝比罗克"}, [33]={npc="杰希卡·雷德帕斯", tgt="杰希卡·雷德帕斯"}, [34]={nodeA="{a:2255}"}, [35]={npc="万能的尼比", tgt="万能的尼比"}, [36]={npc="伊普斯", tgt="伊普斯"}, [37]={npc="伊普斯", tgt="伊普斯"}, [38]={hint="将一块恶魔布交给费伍德森林的伊普斯。"}, [39]={npc="伊普斯", tgt="伊普斯"}, [40]={npc="伊普斯", tgt="伊普斯"}, [41]={hint="将10块腐烂的木头和4个血毒精华交给费伍德森林的伊普斯。"}, [42]={npc="伊普斯", tgt="伊普斯"}, [43]={npc="伊普斯", tgt="伊普斯"}, [44]={hint="到沉没的神庙去，从巨魔们身上获得6支巫毒羽毛。"}, [45]={npc="伊普斯", tgt="伊普斯"}, [46]={npc="伊普斯", tgt="伊普斯"}, [47]={hint="费伍德的伊普斯要求你从三个不同的地区收集三块无暇的恶魔精华，然后把它们交给他。"}, [48]={npc="伊普斯", tgt="伊普斯"}, [49]={npc="伊普斯", tgt="伊普斯", desc="克罗苏斯在费伍德森林北方，要组队。"}, [50]={hint="在费伍德森林的碎痕谷中搜寻克罗苏斯的尸体。当你找到尸体后，在他身上使用魔火，并等待克罗苏斯复生。当这个地狱火被唤醒之后，干掉他，从他的身上拿取克罗苏斯的恶魔之核。", desc="克罗苏斯在费伍德森林北方，要组队。"}, [51]={npc="万能的尼比", tgt="万能的尼比", desc="克罗苏斯在费伍德森林北方，要组队。"}}},
    ["04-50"] = {steps={[2]={npc="普拉特·马克格鲁比", tgt="普拉特·马克格鲁比"}, [3]={npc="特洛亚斯·月风", tgt="特洛亚斯·月风"}, [4]={npc="特洛亚斯·月风", tgt="特洛亚斯·月风"}, [5]={npc="格雷甘·山酒", tgt="格雷甘·山酒"}, [6]={npc="罗克比特", tgt="罗克比特"}, [7]={hint="去菲拉斯找格雷甘·山酒。从他那里问到获取视灵药剂的方法，然后向冬泉谷的多诺瓦·雪山复命。"}, [8]={hint="给特洛亚斯的法杖注入能量，并找到艾奎尼克斯石碑。", desc="后面可以跳上去抄捷径。"}, [9]={npc="沙恩·飘叶", tgt="沙恩·飘叶"}, [10]={npc="艾奎尼克斯石碑", npcObj=true, desc="使用背包里的法杖。"}, [11]={npc="艾奎尼克斯石碑", npcObj=true}, [12]={hint="把10块怒痕雪人的毛皮交给菲拉斯羽月要塞的普拉特·马克格鲁比。"}, [13]={npc="原始雪人毛皮", npcObj=true, tag="可选", desc="打雪人时有掉原始雪人毛皮就右键接。"}, [14]={npc="普拉特·马克格鲁比", tgt="普拉特·马克格鲁比"}, [15]={npc="普拉特·马克格鲁比", tgt="普拉特·马克格鲁比", tag="可选"}, [16]={npc="特洛亚斯·月风", tgt="特洛亚斯·月风"}}},
    ["04-51"] = {steps={[1]={desc="炉石还在冷却就从羽月要塞飞阿斯特兰纳（经奥伯丁），再往北走进费伍德。"}, [2]={npc="阿拉珊蒂丝·银空", tgt="阿拉珊蒂丝·银空"}, [3]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [4]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [5]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [6]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [7]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [8]={npc="塔诺恩·红羽", tgt="塔诺恩·红羽"}, [9]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", desc="回阿斯特兰纳飞刺枝林地，再往北穿过木喉要塞进冬泉谷。"}, [10]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [11]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [12]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [13]={desc="在冬泉熊怪营地 32, 36 一带打熊怪。"}, [14]={npc="格雷戈·格雷斯通", tgt="格雷戈·格雷斯通"}, [15]={npc="格雷戈·格雷斯通", tgt="格雷戈·格雷斯通"}, [16]={desc="会经塔伦迪斯营地转机。"}, [17]={npc="莉芙·雷兹菲克斯", tgt="莉芙·雷兹菲克斯"}, [18]={npc="水之先知伊斯伦", tgt="水之先知伊斯伦"}, [19]={npc="水之先知伊斯伦", tgt="水之先知伊斯伦"}, [21]={npc="炼金师匹斯特苏格", tgt="炼金师匹斯特苏格"}, [22]={text="喝下视灵药剂后保持死亡状态，以灵魂找任务 NPC。"}, [23]={npc="加里杨", tgt="加里杨"}, [24]={npc="加里杨", tgt="加里杨"}, [25]={text="回尸体复活。"}, [26]={npc="明显的墓碑", npcObj=true}, [27]={npc="明显的墓碑", npcObj=true}, [28]={npc="特兰雷克", tgt="特兰雷克"}, [29]={npc="炼金师匹斯特苏格", tgt="炼金师匹斯特苏格"}}},
    ["04-52"] = {name="安戈洛环形山", steps={[2]={npc="林克", tgt="林克"}, [3]={npc="林克", tgt="林克"}, [4]={npc="科琳", tgt="科琳"}, [5]={npc="科琳", tgt="科琳"}, [6]={npc="斯普拉格·弗劳克", tgt="斯普拉格·弗劳克"}, [7]={npc="卡尔纳·雷塔维", tgt="卡尔纳·雷塔维"}, [8]={hint="帮加基森的特兰雷克收集12块极度粘稠的沥青。"}, [9]={npc="克拉兰克", tgt="克拉兰克"}, [10]={hint="到安戈洛环形山的火山中去，从那里的元素身上收集9份安戈洛灰烬，把它们交给棘齿城的莉芙·雷兹菲克斯。"}, [11]={hint="安戈洛尔环形山的克拉兰克要你去找到火羽山中温度最高的地方。"}, [12]={hint="把一份格里什信息素和5份安戈洛的泥土样本交给加基森的炼金师匹斯特苏格。", tag="可选", desc="专程绕路，附近没有其他目标；赶路可跳过。"}, [13]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [14]={npc="克拉兰克", tgt="克拉兰克"}, [15]={npc="克拉兰克", tgt="克拉兰克"}, [16]={npc="林格", tgt="林格", desc="护送任务：组队时等大家进度一致再接，并关掉自动接交。"}, [17]={npc="林格", tgt="林格"}, [18]={npc="斯普拉格·弗劳克", tgt="斯普拉格·弗劳克"}, [19]={npc="A-Me 01", tgt="A-Me 01"}, [20]={npc="A-Me 01", tgt="A-Me 01"}, [21]={npc="A-Me 01", tgt="A-Me 01"}, [22]={hint="把尤尔查的毛皮交给安戈洛环形山入口处的托尔瓦·寻路者。"}, [23]={npc="A-Me 01", tgt="A-Me 01"}, [24]={npc="卡尔纳·雷塔维", tgt="卡尔纳·雷塔维"}, [25]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [26]={text="托尔瓦旁没有飞行点：从他身后的坡道出安戈洛环形山进塔纳利斯，往东北跑到加基森。"}, [27]={npc="特兰雷克", tgt="特兰雷克"}, [28]={npc="炼金师匹斯特苏格", tgt="炼金师匹斯特苏格", tag="可选"}, [29]={desc="会经塞拉摩转机。"}, [30]={npc="莉芙·雷兹菲克斯", tgt="莉芙·雷兹菲克斯"}, [33]={text="在奥伯丁旅店找旅店老板莎希因绑炉石（37.04, 44.13）。"}, [35]={npc="艾瑞拉斯·琥珀", tgt="艾瑞拉斯·琥珀"}, [36]={text="走进鲁瑟兰村的传送门到达纳苏斯。"}, [37]={hint="到达纳苏斯去，用艾瑞丹的瓶子收集月神殿中的祝福之水，然后回到艾瑞丹那儿。"}, [38]={text="走进达纳苏斯的传送门回鲁瑟兰村。"}, [40]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [41]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [42]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [43]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [44]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [45]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [46]={hint="为费伍德森林的艾瑞丹·蓝风收集11只银爪和1颗铁树之心。", tag="可选", desc="专程绕路，附近没有其他目标；赶路可跳过。"}, [47]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风", tag="可选"}, [48]={desc="冷却就走回阿斯特兰纳飞奥伯丁。"}, [49]={desc="这班船中途停南海镇，到米奈希尔港再下船。"}, [51]={npc="史学家卡尼克", tgt="史学家卡尼克", tag="可选"}, [52]={npc="史学家卡尼克", tgt="史学家卡尼克", tag="可选"}, [53]={npc="资深探险家麦格拉斯", tgt="资深探险家麦格拉斯", tag="可选"}, [54]={npc="皇家历史学家阿克瑟努斯", tgt="皇家历史学家阿克瑟努斯"}, [55]={npc="皇家历史学家阿克瑟努斯", tgt="皇家历史