    ["04-54"] = {steps={[1]={text="已开摩根的岗哨就从铁炉堡直接飞过去。没开就飞湖畔镇，沿大路往北进燃烧平原，摩根的岗哨就在入口旁。", tag="还没开这个飞行点，第一次要用跑的"}, [2]={node="摩根的岗哨"}, [3]={npc="奥拉留斯", tgt="奥拉留斯"}, [4]={npc="奥拉留斯", tgt="奥拉留斯"}, [5]={npc="赫林迪斯·河角", tgt="赫林迪斯·河角", tag="可选"}, [6]={npc="丁奇·斯迪波尔", tgt="丁奇·斯迪波尔"}, [7]={npc="麦克斯沃特·尤博格林", tgt="麦克斯沃特·尤博格林"}, [8]={hint="到燃烧平原的索瑞森废墟中去，从索瑞森遗物上搜集信息。当你收集到足够的信息之后，就回到皇家历史学家阿克瑟努斯那里。"}, [9]={hint="把石板拓文交给燃烧平原的麦克斯沃特·尤博格林。"}, [10]={hint="杀掉15个火腹食人魔法师、7个火腹食人魔和7个火腹蛮兵，完成任务之后向奥拉留斯报告。"}, [11]={hint="将龙灵采集器900型和8份雏龙精华交给燃烧平原烈焰峰的丁奇·斯迪波尔。"}, [12]={hint="杀掉15条黑色小龙、10条黑色龙兽和1条黑色幼龙。当你完成任务之后就向赫林迪斯·河角回报。", tag="之后顺路"}, [13]={npc="塞勒斯·萨雷芬图斯", tgt="塞勒斯·萨雷芬图斯", tag="可选"}, [14]={npc="塞勒斯·萨雷芬图斯", tgt="塞勒斯·萨雷芬图斯", tag="可选"}, [15]={npc="丁奇·斯迪波尔", tgt="丁奇·斯迪波尔"}, [16]={npc="麦克斯沃特·尤博格林", tgt="麦克斯沃特·尤博格林"}, [17]={npc="奥拉留斯", tgt="奥拉留斯"}, [18]={npc="奥拉留斯", tgt="奥拉留斯", tag="可选"}, [19]={npc="赫林迪斯·河角", tgt="赫林迪斯·河角", tag="可选"}, [20]={npc="赫林迪斯·河角", tgt="赫林迪斯·河角", tag="可选"}, [21]={hint="找到戈泰什，他应该在巨槌石西面的某处。杀掉戈泰什并把他的头颅交给燃烧平原的奥拉留斯。", tag="可选"}, [22]={hint="奥拉留斯想要50枚黑石徽章。在燃烧平原的兽人身上应该可以找到那些徽章。"}, [23]={npc="奥拉留斯", tgt="奥拉留斯"}, [24]={npc="奥拉留斯", tgt="奥拉留斯", tag="可选"}, [25]={desc="不做真正的主人就直接飞暴风城，跳过下两步。"}, [26]={npc="所罗门镇长", tgt="所罗门镇长", tag="可选"}, [27]={npc="所罗门镇长", tgt="所罗门镇长", tag="可选"}, [29]={npc="伯瓦尔·弗塔根公爵", tgt="伯瓦尔·弗塔根公爵", tag="可选"}, [30]={npc="伯瓦尔·弗塔根公爵", tgt="伯瓦尔·弗塔根公爵", tag="可选"}, [31]={npc="伯瓦尔·弗塔根公爵", tgt="伯瓦尔·弗塔根公爵", tag="可选"}, [32]={npc="伯瓦尔·弗塔根公爵", tgt="伯瓦尔·弗塔根公爵", tag="可选"}, [33]={npc="伯瓦尔·弗塔根公爵", tgt="伯瓦尔·弗塔根公爵", tag="可选"}, [34]={npc="马迪亚斯·肖尔", tgt="马迪亚斯·肖尔", tag="可选"}, [35]={npc="马迪亚斯·肖尔", tgt="马迪亚斯·肖尔", tag="可选"}, [36]={npc="马迪亚斯·肖尔", tgt="马迪亚斯·肖尔", tag="可选"}, [37]={npc="马迪亚斯·肖尔", tgt="马迪亚斯·肖尔", tag="可选"}, [38]={npc="公告员古德曼", tgt="公告员古德曼"}, [39]={npc="武神", tgt="武神", tag="可选"}, [40]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选"}, [41]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选"}, [42]={hint="杀死7头地狱野猪，然后回到部落英雄的灵魂那儿。", tag="可选"}, [43]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选"}, [44]={npc="部落英雄的灵魂", tgt="部