    ["04-55"] = {steps={[1]={desc="已开冰风岗就直接飞冰风岗，跳过下一步。飞行地图没有鹰巢山就飞南海镇，照辛特兰那次的路往东跑到鹰巢山。"}, [2]={text="从鹰巢山往北走山路进西瘟疫之地东南角（65.30, 86.80），再沿路往西到冰风岗。", tag="还没开这个飞行点，第一次要用跑的"}, [3]={node="冰风岗"}, [4]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [5]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [6]={npc="银色黎明军官普尔哈特", tgt="银色黎明军官普尔哈特"}, [7]={npc="银色黎明军官普尔哈特", tgt="银色黎明军官普尔哈特"}, [8]={npc="弗林特·沙多摩尔", tgt="弗林特·沙多摩尔"}, [9]={npc="弗林特·沙多摩尔", tgt="弗林特·沙多摩尔", tag="可选"}, [10]={hint="杀掉悔恨岭中的10个骷髅剥皮者和10个被奴役的食尸鬼。"}, [11]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [12]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [13]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [14]={npc="高阶牧师玛多妮尔", tgt="高阶牧师玛多妮尔"}, [15]={npc="高阶牧师玛多妮尔", tgt="高阶牧师玛多妮尔"}, [16]={hint="使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。"}, [17]={hint="到西瘟疫之地的费尔斯通农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带费尔斯通农场的空瓶来采集瘟疫之锅中的毒药样本。"}, [18]={npc="瘟疫之锅", npcObj=true}, [19]={npc="瘟疫之锅", npcObj=true}, [20]={npc="詹妮丝·费尔斯通", tgt="詹妮丝·费尔斯通"}, [21]={npc="詹妮丝的包裹", npcObj=true}, [22]={npc="詹妮丝的包裹", npcObj=true}, [23]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [24]={npc="高阶牧师玛多妮尔", tgt="高阶牧师玛多妮尔"}, [25]={npc="高阶牧师玛多妮尔", tgt="高阶牧师玛多妮尔"}, [26]={hint="到西瘟疫之地的达尔松之泪去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带达尔松之泪的空瓶来采集瘟疫之锅中的毒药样本。"}, [27]={npc="瘟疫之锅", npcObj=true}, [28]={npc="瘟疫之锅", npcObj=true}, [29]={npc="高阶牧师玛多妮尔", tgt="高阶牧师玛多妮尔"}, [30]={npc="高阶牧师玛多妮尔", tgt="高阶牧师玛多妮尔"}, [31]={npc="纳萨尼尔·杜马", tgt="纳萨尼尔·杜马"}, [32]={hint="到西瘟疫之地的嚎哭鬼屋去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带嚎哭鬼屋的空瓶来采集瘟疫之锅中的毒药样本。"}, [33]={npc="瘟疫之锅", npcObj=true}, [34]={npc="瘟疫之锅", npcObj=true}, [35]={npc="穆格雷斯·深水", tgt="穆格雷斯·深水"}, [36]={hint="消灭8只生病的狼，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。"}, [37]={npc="穆格雷斯·深水", tgt="穆格雷斯·深水"}, [38]={npc="穆格雷斯·深水", tgt="穆格雷斯·深水"}, [39]={hint="消灭8只生病的灰熊，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。"}, [40]={npc="穆格雷斯·深水", tgt="穆格雷斯·深水"}, [41]={npc="穆格雷斯·深水", tgt="穆格雷斯·深水"}, [42]={text="沿路跑到这个点。"}, [43]={text="在鹰巢山旅店绑炉石（13.80, 41.60）。"}, [44]={npc="科泰罗的宝藏", npcObj=true}, [45]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [46]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [47]={hint="收集20个爪牙的天灾石，并将它们交给西瘟疫之地的高阶牧师赛尔丹尼斯。"}, [48]={npc="高阶牧师赛尔丹尼斯", tgt="高阶牧师赛尔丹尼斯"}, [49]={npc="高阶牧师赛尔丹尼斯", tgt="高阶牧师赛尔丹尼斯"}, [50]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [51]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特", desc="交任务取得力量之石。"}, [52]={hint="前往沉没的神庙，从巨魔守护者们身上取得巫毒羽毛，然后把它们交给阿什拉姆·瓦罗菲斯特。", desc="交任务取得力量之石。"}, [53]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特", desc="交任务取得力量之石。"}}},
    ["04-56"] = {steps={[1]={text="从鹰巢山往北走山路进西瘟疫之地，再往东过索多里尔河进东瘟疫之地，提里奥·弗丁就在入口旁的小屋。"}, [2]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [3]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [4]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [5]={hint="杀掉20条瘟疫幼犬、5条瘟疫犬和5条狂怒的瘟疫犬。任务完成之后向提里奥·弗丁复命。"}, [6]={hint="杀死30只瘟疫蝙蝠，然后向提里奥·弗丁复命。"}, [7]={hint="在东瘟疫之地搜索腐肉虫和腐肉吞噬者。杀了它们并收集它们的肉。当你收集到15块食腐虫肉块之后，就回到提里奥·弗丁那里。"}, [8]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [9]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [10]={hint="找到帕米拉的洋娃娃。", desc="在达隆郡废屋捡头、左半身、右半身三个部件，右键组合。"}, [11]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [12]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [13]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [14]={npc="尼古拉斯·瑟伦霍夫公爵", tgt="尼古拉斯·瑟伦霍夫公爵"}, [15]={node="圣光之愿礼拜堂"}, [16]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯"}, [17]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯", tag="可选"}, [18]={npc="护理者奥林", tgt="护理者奥林"}, [19]={hint="释放15个达隆郡居民的灵魂，然后返回卡林·雷德帕斯身边。", tag="可选", desc="专程绕路，附近没有其他目标；赶路可跳过。"}, [20]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [21]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [22]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [23]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [24]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [25]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [26]={hint="到东瘟疫之地最南端的墓室去找回泰兰之锤。完成目标之后，返回提里奥·弗丁那里。"}, [27]={hint="将塞达尔的头颅交给圣光之愿礼拜堂的护理者奥林。"}, [28]={npc="破损的卷轴", npcObj=true}, [29]={hint="搜寻东瘟疫之地，寻找\"凋零者\"的线索以及失踪的军情七处密探。如果你找到任何军情七处徽章，就把它们交给冰风岗的弗林特·沙多摩尔。", tag="可选"}, [30]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [31]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [32]={npc="护理者奥林", tgt="护理者奥林"}, [33]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯", tag="可选"}}},
    ["04-53"] = {steps={[1]={desc="会经冰风岗或鹰巢山转机；飞行地图没有南海镇就照旧飞暴风城，到港口搭船去奥伯丁。"}, [2]={desc="南海镇码头就有往奥伯丁的船，比飞暴风城转船快；改飞暴风城的话在暴风城港口上船。"}, [4]={hint="冬泉谷的多诺瓦·雪山要你去杀死8个冬泉探路者、8个冬泉巢穴守卫和8个冬泉图腾师。"}, [5]={hint="萨尔法要你去击杀8个冬泉萨满祭司、8个冬泉巢穴守卫，以及8个冬泉巨熊怪。萨尔法就在冬泉谷的木喉要塞入口外。", tag="需游戏内实测"}, [6]={npc="空的火酒瓶", npcObj=true, desc="右键背包里的空的火酒瓶接任务。"}, [7]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [8]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [9]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [10]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [11]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [12]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [13]={hint="从冬泉谷收集10片月光羽毛，然后将它们带给鲁瑟兰村的艾瑞拉斯·琥珀。"}, [14]={npc="萨尔法", tgt="萨尔法", tag="需游戏内实测"}, [15]={npc="死木蒸锅", npcObj=true}, [16]={npc="死木蒸锅", npcObj=true}, [17]={desc="从死木蒸锅往南走到刺枝林地飞行点（62.49, 24.24）起飞，会经奥伯丁转机。"}, [18]={npc="艾瑞拉斯·琥珀", tgt="艾瑞拉斯·琥珀"}, [19]={npc="艾瑞拉斯·琥珀", tgt="艾瑞拉斯·琥珀"}, [20]={npc="达蕾恩·轻风", tgt="达蕾恩·轻风"}, [22]={npc="哈鲁·维格索斯", tgt="哈鲁·维格索斯"}, [23]={npc="维恩德·夜风", tgt="维恩德·夜风"}, [24]={npc="维恩德·夜风", tgt="维恩德·夜风"}, [25]={npc="加隆·石矛", tgt="加隆·石矛"}, [26]={npc="加隆·石矛", tgt="加隆·石矛"}, [27]={npc="加隆·石矛", tgt="加隆·石矛"}, [28]={npc="加隆·石矛", tgt="加隆·石矛"}, [29]={hint="使用加隆的镐来寻找四块上层精灵遗物的碎片，把它们交给东瘟疫之地的奥萝拉。"}, [30]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [31]={npc="破损的箱子", npcObj=true}, [32]={npc="破损的箱子", npcObj=true}, [33]={npc="加隆的马车", npcObj=true}, [34]={npc="加隆的马车", npcObj=true}, [35]={hint="从雪地中拾起加隆的补给物资，然后寻找盗取加隆所说的护符的枭兽。"}, [36]={npc="兰莎尔拉", tgt="兰莎尔拉"}, [37]={npc="兰莎尔拉", tgt="兰莎尔拉"}, [38]={hint="在兰莎尔拉尝试激活艾露恩祭坛的过程中保护她。然后将你的发现报告给鲁瑟兰村的艾瑞拉斯·琥珀。"}, [39]={npc="加隆·石矛", tgt="加隆·石矛"}, [41]={npc="艾瑞拉斯·琥珀", tgt="艾瑞拉斯·琥珀"}, [42]={npc="艾瑞拉斯·琥珀", tgt="艾瑞拉斯·琥珀"}, [43]={text="走进鲁瑟兰村的传送门到达纳苏斯。"}, [44]={npc="大德鲁伊范达尔·鹿盔", tgt="大德鲁伊范达尔·鹿盔"}}},
    ["04-57"] = {name="西瘟疫之地", steps={[1]={desc="炉石还在冷却就走传送门回鲁瑟兰村，飞奥伯丁，搭往米奈希尔港的船在南海镇下船，再飞冰风岗。"}, [2]={desc="飞行地图没有冰风岗就从鹰巢山往北走山路进西瘟疫之地，再往西跑到冰风岗。"}, [3]={npc="高阶牧师玛多妮尔", tgt="高阶牧师玛多妮尔"}, [4]={npc="弗林特·沙多摩尔", tgt="弗林特·沙多摩尔", tag="可选"}, [5]={npc="高阶牧师玛多妮尔", tgt="高阶牧师玛多妮尔"}, [6]={npc="玛莱恩·雷德帕斯", tgt="玛莱恩·雷德帕斯"}, [7]={npc="玛莱恩·雷德帕斯", tgt="玛莱恩·雷德帕斯"}, [8]={hint="把约瑟夫的结婚戒指交给安多哈尔的克罗米。"}, [9]={npc="克罗米", tgt="克罗米"}, [10]={npc="克罗米", tgt="克罗米"}, [11]={npc="克罗米", tgt="克罗米"}, [12]={hint="把《达隆郡的历史》交给安多哈尔的克罗米。"}, [13]={hint="在安多哈尔的一处仓库附近使用时光置换器，使时光寄生虫现身。"}, [14]={npc="克罗米", tgt="克罗米"}, [15]={npc="克罗米", tgt="克罗米"}, [16]={npc="克罗米", tgt="克罗米"}, [17]={desc="安多哈尔没有飞行点，先往南走回冰风岗再飞。"}, [18]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯"}, [19]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯", tag="可选"}, [20]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯"}, [21]={hint="到东瘟疫之地东北部的北谷去，找到失落荣耀的象征。完成目标之后向提里奥·弗丁复命。"}, [22]={hint="杀了渗透者哈米亚，用他的钥匙开启墓室后的一堆泥土。"}, [23]={npc="奥萝拉", tgt="奥萝拉"}, [24]={npc="奥萝拉", tgt="奥萝拉"}, [25]={hint="在东瘟疫之地的蚁丘上使用空的白蚁瓶。当你收集了100只瘟疫白蚁之后，就回到西瘟疫之地的冰风岗去找纳萨尼尔·杜马。"}, [26]={hint="将霍古斯的颅骨和马杜克的破碎之剑交给圣光之愿礼拜堂的卡林·雷德帕斯。", tag="可选", desc="专程绕路，附近没有其他目标；赶路可跳过。"}, [27]={npc="一堆泥土", npcObj=true}, [28]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [29]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [30]={hint="把达维的圣契和雷德帕斯之盾交给卡林·雷德帕斯。"}, [31]={hint="到西瘟疫之地的盖罗恩农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带盖罗恩农场的空瓶来采集瘟疫之锅中的毒药样本。"}, [32]={npc="瘟疫之锅", npcObj=true}, [33]={npc="瘟疫之锅", npcObj=true}, [34]={npc="画家瑞弗蕾", tgt="画家瑞弗蕾"}, [35]={npc="高阶牧师玛多妮尔", tgt="高阶牧师玛多妮尔"}, [36]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [37]={npc="指挥官阿什拉姆·瓦罗菲斯特", tgt="指挥官阿什拉姆·瓦罗菲斯特"}, [38]={npc="纳萨尼尔·杜马", tgt="纳萨尼尔·杜马"}, [39]={npc="纳萨尼尔·杜马", tgt="纳萨尼尔·杜马"}, [40]={npc="白蚁桶", npcObj=true}, [41]={npc="白蚁桶", npcObj=true}, [42]={npc="科尔斯塔·迪普沙东", tgt="科尔斯塔·迪普沙东"}, [43]={hint="杀死2个血色医护员、2个血色猎人、2个血色魔法师和2个血色骑士，然后回到西瘟疫之地的科尔斯塔·迪普沙东那儿。"}, [44]={npc="科尔斯塔·迪普沙东", tgt="科尔斯塔·迪普沙东"}, [45]={npc="科尔斯塔·迪普沙东", tgt="科尔斯塔·迪普沙东"}, [46]={hint="杀掉猎人莱德雷和骑士杜尔根，然后向西瘟疫之地的科尔斯塔·迪普沙东复命。"}, [47]={npc="科尔斯塔·迪普沙东", tgt="科尔斯塔·迪普沙东"}, [48]={npc="